// SVG Sun with rotation and pop-in spring animation
const Sun: React.FC<{
  x: number;
  y: number;
  size: number;
  color: string;
  frame: number;
  fps: number;
}> = ({ x, y, size, color, frame, fps }) => {
  const popSpring = spring({
    frame,
    fps,
    config: { mass: 0.8, stiffness: 120, damping: 12 },
    delay: 5,
  });

  const rotate = (frame * 0.4) % 360;

  return (
    <div
      style={{
        position: "absolute",
        left: x - size / 2,
        top: y - size / 2,
        width: size,
        height: size,
        transform: `scale(${popSpring}) rotate(${rotate}deg)`,
        transformOrigin: "center",
        transition: "none",
        zIndex: 1,
      }}
    >
      <svg width={size} height={size} viewBox="0 0 100 100">
        <g fill={color}>
          {[...Array(12)].map((_, i) => {
            const angle = (i * 360) / 12;
            return (
              <path
                key={i}
                d="M 50 10 L 54 26 L 46 26 Z"
                transform={`rotate(${angle} 50 50)`}
              />
            );
          })}
        </g>
        <circle cx="50" cy="50" r="24" fill={color} />
      </svg>
    </div>
  );
};

