// Dynamic particle splash effect
const Splash: React.FC<{
  centerX: number;
  centerY: number;
  color: string;
  frame: number;
  fps: number;
  delay: number;
}> = ({ centerX, centerY, color, frame, fps, delay }) => {
  const splashProgress = spring({
    frame: frame - delay,
    fps,
    config: { mass: 1.1, stiffness: 85, damping: 14 },
  });

  const numDroplets = 8;
  const droplets = [...Array(numDroplets)].map((_, i) => {
    const angle = (i * 360) / numDroplets + 22.5;
    const dist = interpolate(splashProgress, [0, 1], [10, 150], {
      extrapolateRight: "clamp",
    });
    const scale = interpolate(splashProgress, [0, 0.6, 1], [0, 1.3, 0], {
      extrapolateRight: "clamp",
    });

    const x = centerX + Math.cos((angle * Math.PI) / 180) * dist;
    const y = centerY + Math.sin((angle * Math.PI) / 180) * dist;

    return { x, y, scale, angle };
  });

  return (
    <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", pointerEvents: "none", zIndex: 3 }}>
      {droplets.map((d, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: d.x - 12,
            top: d.y - 12,
            width: 24,
            height: 24,
            transform: `scale(${d.scale}) rotate(${d.angle + 90}deg)`,
            transformOrigin: "center",
            transition: "none",
          }}
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path
              d="M12 2C12 2 6 10 6 14C6 17.3 8.7 20 12 20C15.3 20 18 17.3 18 14C18 10 12 2 12 2Z"
              fill={color}
            />
          </svg>
        </div>
      ))}
    </div>
  );
};

// Dynamic Waves component at the bottom
